  1	/**
  2	 * AuthorView — the Dungeon Builder's real, in-game home (`/author`
  3	 * AppView, rpg-project#194). Mounts the SAME `DungeonBuilderConcept`
  4	 * component tree the Concepts Lab dev sandbox mounts
  5	 * (`concepts/ConceptsView.tsx`) — one component tree, two mounts, per the
  6	 * graduation's own rule. This is the LIVE mount: no `forceFixtures`, so
  7	 * `usePutDungeonPreview`'s own mount-time probe decides live-vs-fixtures
  8	 * against whatever server this build actually talks to, exactly as it
  9	 * always has.
 10	 *
 11	 * The button that routes here (`DungeonBuilderHomeButton.tsx`, mounted on
 12	 * Home) is gated by its own separate probe (`useAuthoringGate.ts`) so a
 13	 * deployed build with authoring off server-side never shows a way in at
 14	 * all — this component doesn't re-check that gate itself; by the time
 15	 * it's mounted, the gate has already said yes.
 16	 */
 17	import { DungeonBuilderConcept } from './DungeonBuilderConcept';
 18	
 19	interface AuthorViewProps {
 20	  onBack: () => void;
 21	}
 22	
 23	export function AuthorView({ onBack }: AuthorViewProps) {
 24	  return (
 25	    <div className="max-w-7xl mx-auto">
 26	      <div className="flex items-center gap-4 mb-6">
 27	        <button
 28	          onClick={onBack}
 29	          className="px-3 py-1.5 rounded text-sm"
 30	          style={{
 31	            backgroundColor: 'var(--bg-secondary)',
 32	            color: 'var(--text-primary)',
 33	            border: '1px solid var(--border-primary)',
 34	          }}
 35	        >
 36	          Back
 37	        </button>
 38	        <h1
 39	          className="text-3xl font-bold"
 40	          style={{
 41	            fontFamily: 'Cinzel, serif',
 42	            color: 'var(--text-primary)',
 43	          }}
 44	        >
 45	          Dungeon Builder
 46	        </h1>
 47	      </div>
 48	      <DungeonBuilderConcept />
 49	    </div>
 50	  );
 14	// Service for D&D 5e character creation and management
 15	// Supports both wizard-style step-by-step creation and free-form editing
 16	service CharacterService {
 17	  // Draft lifecycle
 18	  rpc CreateDraft(CreateDraftRequest) returns (CreateDraftResponse);
 19	  rpc GetDraft(GetDraftRequest) returns (GetDraftResponse);
 20	  rpc ListDrafts(ListDraftsRequest) returns (ListDraftsResponse);
 21	  rpc DeleteDraft(DeleteDraftRequest) returns (DeleteDraftResponse);
 22	
 23	  // Section-based updates (supports skip-around editing)
 24	  rpc UpdateName(UpdateNameRequest) returns (UpdateNameResponse);
 25	  rpc UpdateRace(UpdateRaceRequest) returns (UpdateRaceResponse);
 26	  rpc UpdateClass(UpdateClassRequest) returns (UpdateClassResponse);
 27	  rpc UpdateBackground(UpdateBackgroundRequest) returns (UpdateBackgroundResponse);
 28	  rpc UpdateAbilityScores(UpdateAbilityScoresRequest) returns (UpdateAbilityScoresResponse);
 29	  rpc UpdateSkills(UpdateSkillsRequest) returns (UpdateSkillsResponse);
 30	  rpc UpdateAppearance(UpdateAppearanceRequest) returns (UpdateAppearanceResponse);
 31	
 32	  // Validation
 33	  rpc ValidateDraft(ValidateDraftRequest) returns (ValidateDraftResponse);
 34	
 35	  // Get a preview of what the character would look like if finalized
 36	  rpc GetDraftPreview(GetDraftPreviewRequest) returns (GetDraftPreviewResponse);
 37	
 38	  // Character finalization
 39	  rpc FinalizeDraft(FinalizeDraftRequest) returns (FinalizeDraftResponse);
 40	
 41	  // Completed character operations
 42	  rpc GetCharacter(GetCharacterRequest) returns (GetCharacterResponse);
 43	  rpc ListCharacters(ListCharactersRequest) returns (ListCharactersResponse);
 44	  rpc DeleteCharacter(DeleteCharacterRequest) returns (DeleteCharacterResponse);
 45	
194	service LobbyService {
195	  // CreateLobby starts a new WAITING lobby; the caller becomes host.
196	  rpc CreateLobby(CreateLobbyRequest) returns (CreateLobbyResponse);
197	
198	  // JoinLobby is idempotent and rebinds character_id for an existing member.
199	  // FailedPrecondition if the lobby already STARTED or the party is at cap.
200	  rpc JoinLobby(JoinLobbyRequest) returns (JoinLobbyResponse);
201	
202	  // SetReady toggles the caller's ready flag; broadcast as member_ready.
203	  rpc SetReady(SetReadyRequest) returns (SetReadyResponse);
204	
205	  // LeaveLobby removes the caller, pre-start only. Host leaving migrates the
206	  // host role (host_changed); the last member leaving lets the lobby expire
207	  // via TTL rather than dissolving explicitly.
208	  rpc LeaveLobby(LeaveLobbyRequest) returns (LeaveLobbyResponse);
209	
210	  // StartEncounter is host-only and all-ready gated. Builds the toolkit
211	  // encounter, persists it, then emits encounter_started. WAITING -> STARTED
212	  // is terminal — this is the only way a lobby becomes an encounter, replacing
213	  // EncounterService.CreateEncounter's single-caller construction path.
214	  rpc StartEncounter(StartEncounterRequest) returns (StartEncounterResponse);
215	
154	service AuthoringService {
155	  // PutDungeon is absent from the server's reflection list
156	  // (Unimplemented) unless the server was started with the authoring
157	  // gate enabled -- see plan.md S1.
158	  rpc PutDungeon(PutDungeonRequest) returns (PutDungeonResponse);
159	}

