### AC Calculation with Defense
```go
func (c *Character) CalculateAC() int {
    baseAC := 10 + c.abilityScores.Modifier(constants.DEX)

    // Apply armor bonuses (from equipment)
    armorAC := c.getArmorAC()
    if armorAC > baseAC {
        baseAC = armorAC
    }

    // Apply fighting style bonuses
    if c.fightingStyle == \"defense\" && c.hasArmor() {
        baseAC += 1
    }

    return baseAC
}
